import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";

function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch("http://localhost:8000/api/productes");

      if (!response.ok) {
        throw new Error("Error al obtenir els productes");
      }

      const data = await response.json();

      // ✅ TU API DEVUELVE UN ARRAY DIRECTO
      setProducts(data);
    } catch (err) {
      console.error(err);
      setError("Error al obtenir els productes");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  if (products.length === 0) {
    return <p className="mt-3">No hi ha productes disponibles</p>;
  }

  return (
    <div className="mt-4">
      <h2>Llista de Productes</h2>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Nom</th>
            <th>Referència</th>
            <th>Quantitat</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {products.map((producte) => (
            <tr key={producte.id}>
              <td>{producte.id}</td>
              <td>{producte.nom}</td>
              <td>{producte.referencia}</td>
              <td>{producte.quantitat}</td>
              <td>
                <Button variant="warning" size="sm" className="me-2">
                  Editar
                </Button>
                <Button variant="danger" size="sm">
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </div>
  );
}

export default ProductsList;
